package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserMinimalBase;
import com.fasterxml.jackson.core.json.JsonReadContext;
import com.fasterxml.jackson.core.json.JsonWriteContext;
import com.fasterxml.jackson.core.util.ByteArrayBuilder;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for TokenBuffer.writeNumber(int i)
 */
public class TokenBuffer_writeNumber_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    @Test
    public void testWriteNumber_PositiveInteger() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        int testValue = 123;

        buffer.writeNumber(testValue);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        Assert.assertEquals(testValue, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_NegativeInteger() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        int testValue = -456;

        buffer.writeNumber(testValue);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        Assert.assertEquals(testValue, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_Zero() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        int testValue = 0;

        buffer.writeNumber(testValue);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        Assert.assertEquals(testValue, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_IntegerMaxValue() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        int testValue = Integer.MAX_VALUE;

        buffer.writeNumber(testValue);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        Assert.assertEquals(testValue, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_IntegerMinValue() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        int testValue = Integer.MIN_VALUE;

        buffer.writeNumber(testValue);

        JsonParser parser = buffer.asParser();
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.currentToken());
        Assert.assertEquals(testValue, parser.getIntValue());
    }

    @Test
    public void testWriteNumber_Sequence() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);

        buffer.writeStartObject();
        buffer.writeFieldName("a");
        buffer.writeNumber(1);
        buffer.writeFieldName("b");
        buffer.writeNumber(2);
        buffer.writeEndObject();

        JsonParser parser = buffer.asParser();

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        Assert.assertEquals("a", parser.getCurrentName());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        Assert.assertEquals(1, parser.getIntValue());

        Assert.assertEquals("b", parser.getCurrentName());
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
        Assert.assertEquals(2, parser.getIntValue());

        Assert.assertEquals(JsonToken.END_OBJECT, parser.nextToken());
        Assert.assertNull(parser.endObject());
    }

    @Test
    public void testWriteNumber_SerializeToGenerator() throws IOException {
        TokenBuffer buffer = new TokenBuffer(mapper);
        buffer.writeNumber(99);

        // Use a real generator to ensure serialization works as expected
        JsonGenerator gen = mapper.getFactory().createGenerator(System.out);
        buffer.serialize(gen);
        gen.close();
        // This test primarily ensures no exception is thrown during the serialization process
    }
}
